patches.new:
@media screen and (min-width: 375px) and (max-width: 1060px) {
 #navcontent { grid-template-columns: repeat(6,minmax(max-content,1fr)); }
 #navbar #logo { grid-column: 1 / 4; }
 #navbar #readbutton { grid-column: 4 / -1; justify-self: end; white-space: nowrap; }
 #navbar .navbutton:not(#readbutton) { font-size: 13px; }
}
@media screen and (max-width: 720px) {

if (reading) {
    out.focus({preventScroll: true});
} else {
    editor.refresh();
    if (window.matchMedia('(pointer: fine)').matches) editor.focus();
}

